// Neon Runner – minimal endless runner
// Canvas element with id="game" must exist in the page.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 200;

  // Game settings
  const PLAYER_SIZE = 20;
  const GRAVITY = 0.6;
  const JUMP_VELOCITY = -12;
  const OBSTACLE_WIDTH = 20;
  const OBSTACLE_GAP = 150; // distance between obstacles
  const SPEED = 4;

  let player = { x: 50, y: height - PLAYER_SIZE, vy: 0, onGround: true };
  let obstacles = [];
  let frameCount = 0;
  let running = true;

  function spawnObstacle() {
    const type = Math.random() < 0.5 ? 'spike' : 'gap';
    const x = width;
    if (type === 'spike') {
      obstacles.push({ type, x, y: height - PLAYER_SIZE, w: OBSTACLE_WIDTH, h: PLAYER_SIZE });
    } else {
      // gap: just a space the player must jump over; represent as invisible obstacle for collision check
      obstacles.push({ type, x, w: OBSTACLE_WIDTH, gap: true });
    }
  }

  function update() {
    // Player physics
    player.vy += GRAVITY;
    player.y += player.vy;
    if (player.y >= height - PLAYER_SIZE) {
      player.y = height - PLAYER_SIZE;
      player.vy = 0;
      player.onGround = true;
    } else {
      player.onGround = false;
    }

    // Move obstacles
    obstacles.forEach(o => o.x -= SPEED);
    // Remove off‑screen obstacles
    obstacles = obstacles.filter(o => o.x + o.w > 0);

    // Spawn new obstacles
    if (frameCount % Math.floor(OBSTACLE_GAP / SPEED) === 0) spawnObstacle();

    // Collision detection
    for (const o of obstacles) {
      if (o.type === 'spike') {
        const collides =
          player.x < o.x + o.w &&
          player.x + PLAYER_SIZE > o.x &&
          player.y < o.y + o.h &&
          player.y + PLAYER_SIZE > o.y;
        if (collides) running = false;
      } else if (o.type === 'gap') {
        // gap is a hole: if player is over the gap and not jumping enough, lose
        const overGap = player.x + PLAYER_SIZE > o.x && player.x < o.x + o.w;
        if (overGap && player.onGround) { running = false; break; }
      }
    }

    frameCount++;
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // draw player (neon cyan)
    ctx.fillStyle = '#00ffff';
    ctx.fillRect(player.x, player.y, PLAYER_SIZE, PLAYER_SIZE);
    // draw obstacles
    ctx.fillStyle = '#ff00ff'; // neon magenta for spikes
    obstacles.forEach(o => {
      if (o.type === 'spike') {
        ctx.fillRect(o.x, o.y, o.w, o.h);
      } else if (o.type === 'gap') {
        // visualize gap as a dark rectangle (optional)
        ctx.fillStyle = '#222';
        ctx.fillRect(o.x, height - PLAYER_SIZE, o.w, PLAYER_SIZE);
        ctx.fillStyle = '#ff00ff';
      }
    });
  }

  function loop() {
    if (!running) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
      return;
    }
    update();
    draw();
    requestAnimationFrame(loop);
  }

  // Input – tap/click to jump
  window.addEventListener('mousedown', () => { if (player.onGround) player.vy = JUMP_VELOCITY; });
  window.addEventListener('touchstart', e => { e.preventDefault(); if (player.onGround) player.vy = JUMP_VELOCITY; }, { passive: false });

  // start
  requestAnimationFrame(loop);
})();
